window.XP_DATA = {"title":"What Really Happens Before You Click Run","titleZh":"点下 Run 之前，到底发生了什么？","duration":452.25,"poster":{"t":5.68,"runspot":"[data-seq=\"A\"] .ot-page .pill"},"chapters":[{"t":0.0,"en":"The end of a long story","zh":"一个漫长故事的结尾","act":"A"},{"t":17.96,"en":"A dark box and a button","zh":"漆黑的机箱和一个按钮","act":"B"},{"t":38.43,"en":"The first instruction","zh":"第一条指令","act":"B"},{"t":52.27,"en":"Training the memory","zh":"训练内存","act":"B"},{"t":65.08,"en":"A signed bootloader","zh":"签了名的引导程序","act":"B"},{"t":80.15,"en":"The kernel unpacks itself","zh":"内核自己解压自己","act":"C"},{"t":94.93,"en":"The kernel sets up the world","zh":"内核搭好世界","act":"C"},{"t":108.77,"en":"Process one","zh":"1 号进程","act":"C"},{"t":126.1,"en":"systemd starts the services","zh":"systemd 启动服务","act":"C"},{"t":142.29,"en":"A password that is never stored","zh":"从不保存的密码","act":"C"},{"t":161.18,"en":"sudo apt install clang","zh":"sudo apt install clang","act":"D"},{"t":176.41,"en":"DNS: from a name to a number","zh":"DNS：从名字到数字","act":"D"},{"t":190.19,"en":"Down the tower, across the sea","zh":"下到塔底，穿过海底","act":"D"},{"t":217.23,"en":"Handshake and slow start","zh":"握手与慢启动","act":"D"},{"t":231.78,"en":"77,000 packets","zh":"7.7 万个数据包","act":"D"},{"t":247.15,"en":"The seal, not the road","zh":"认封印，不认路","act":"E"},{"t":264.38,"en":"An archive inside an archive","zh":"归档里面套着归档","act":"E"},{"t":281.63,"en":"PATH","zh":"PATH","act":"E"},{"t":293.46,"en":"Who compiled the compiler?","zh":"谁编译了编译器？","act":"E"},{"t":312.76,"en":"The editor opens","zh":"打开编辑器","act":"E"},{"t":326.07,"en":"One keystroke: the H","zh":"一次按键：H","act":"F"},{"t":356.76,"en":"Half-compiled as you type","zh":"边打字边“半编译”","act":"F"},{"t":378.71,"en":"Fingertip to photons","zh":"从指尖到光子","act":"F"},{"t":395.32,"en":"Ctrl+S: page cache to cells","zh":"Ctrl+S：从页缓存到存储单元","act":"G"},{"t":422.55,"en":"All that, and back to the button","zh":"这一切，回到按钮","act":"G"}],"acts":{"A":{"en":"Rewind","zh-Hans":"倒带"},"B":{"en":"Power on","zh-Hans":"通电"},"C":{"en":"Bootstrapping","zh-Hans":"自举"},"D":{"en":"The internet","zh-Hans":"互联网"},"E":{"en":"Install and set up","zh-Hans":"安装与配置"},"F":{"en":"One keystroke","zh-Hans":"一次按键"},"G":{"en":"Save, and back to the button","zh-Hans":"保存，回到按钮"}},"captionsZh":[{"t0":1.22,"t1":5.09,"text":"一个写好的 hello world，光标停在 Run 上"},{"t0":5.46,"t1":7.38,"text":"看起来，这像是某件事的开始"},{"t0":7.75,"t1":10.93,"text":"其实，这是一个漫长故事的结尾"},{"t0":11.3,"t1":13.11,"text":"那么，我们倒带回去"},{"t0":18.78,"t1":20.32,"text":"一路倒回最开始"},{"t0":20.69,"t1":24.01,"text":"回到一个漆黑、安静的机箱，和一个按钮"},{"t0":24.63,"t1":25.74,"text":"你按下了它"},{"t0":26.11,"t1":29.89,"text":"电源把各路电压稳定下来，发出一个信号"},{"t0":29.95,"t1":31.06,"text":"power good（电源正常）"},{"t0":31.43,"t1":36.44,"text":"严格来说，一台藏在你电脑里的小电脑会最先醒来"},{"t0":36.81,"t1":38.23,"text":"这个嘛，咱们就不展开了"},{"t0":38.85,"t1":44.31,"text":"接着，处理器退出复位，从一个固定地址取出第一条指令"},{"t0":44.35,"t1":47.05,"text":"就在 4 GB 往下数 16 个字节处"},{"t0":47.42,"t1":48.62,"text":"那里不是内存"},{"t0":48.99,"t1":51.57,"text":"而是一块闪存芯片，里面存着固件"},{"t0":52.69,"t1":55.53,"text":"而且，这时往往连能用的内存都还没有"},{"t0":55.9,"t1":58.98,"text":"于是固件先借用处理器自己的缓存"},{"t0":59.02,"t1":64.88,"text":"同时训练内存，一点点微调每条数据线的时序\n直到每一位数据都干干净净地到达"},{"t0":65.5,"t1":67.58,"text":"然后，它唤醒机器的其余部分"},{"t0":67.62,"t1":70.38,"text":"打开一个 FAT 格式的小分区"},{"t0":70.42,"t1":73.04,"text":"这种文件系统，比它的大多数用户年纪还大"},{"t0":73.08,"t1":74.55,"text":"再加载一个引导程序"},{"t0":74.92,"t1":79.75,"text":"开启安全启动时，第一个运行的 Linux 组件是微软签的名"},{"t0":80.37,"t1":82.16,"text":"引导程序加载内核"},{"t0":82.2,"t1":83.84,"text":"内核会自己把自己解压出来"},{"t0":84.21,"t1":85.99,"text":"这就是为什么开机叫 booting"},{"t0":86.03,"t1":87.68,"text":"是 bootstrapping（自举）的简称"},{"t0":87.76,"t1":90.36,"text":"揪着自己的鞋带，把自己提起来"},{"t0":90.73,"t1":92.36,"text":"人可做不到"},{"t0":92.73,"t1":94.73,"text":"电脑却每天早上都在做"},{"t0":95.35,"t1":98.85,"text":"内核搭好一个世界，以后每个程序都住在里面"},{"t0":98.96,"t1":101.85,"text":"页表、调度器、中断"},{"t0":102.22,"t1":104.92,"text":"它唤醒其他 CPU 核心，加载驱动"},{"t0":104.96,"t1":108.57,"text":"挂载磁盘，然后只启动一个程序"},{"t0":109.19,"t1":110.57,"text":"1 号进程"},{"t0":110.94,"t1":113.44,"text":"你今天要运行的一切：桌面"},{"t0":113.48,"t1":116.43,"text":"编辑器、编译器，都是它的子进程"},{"t0":116.47,"t1":119.44,"text":"或孙进程，或曾曾孙进程"},{"t0":119.81,"t1":122.91,"text":"每个进程，生来都是另一个进程的副本"},{"t0":123.28,"t1":125.9,"text":"家谱就从这里开始"},{"t0":126.52,"t1":131.01,"text":"它叫 systemd，会同时启动几十个服务"},{"t0":131.38,"t1":134.03,"text":"一个向路由器申请网络地址"},{"t0":134.4,"t1":136.35,"text":"一个启动登录界面"},{"t0":136.72,"t1":139.3,"text":"而窗口合成器接管了显卡"},{"t0":139.34,"t1":142.09,"text":"从此，每一帧画面都由它来画"},{"t0":142.71,"t1":144.26,"text":"你输入密码"},{"t0":144.63,"t1":146.06,"text":"密码本身从来不会被保存"},{"t0":146.43,"t1":149.55,"text":"系统把你输入的内容算成哈希，去比对另一个哈希"},{"t0":149.59,"t1":151.48,"text":"它存在一个叫 shadow 的文件里"},{"t0":151.85,"t1":152.81,"text":"对上了"},{"t0":153.18,"t1":153.95,"text":"欢迎"},{"t0":154.57,"t1":156.55,"text":"按下按钮几秒之后"},{"t0":156.78,"t1":159.51,"text":"一个桌面，两百来个进程"},{"t0":159.55,"t1":161.38,"text":"可还是没有编译器"},{"t0":162.0,"t1":163.49,"text":"于是你打开一个终端"},{"t0":163.56,"t1":166.08,"text":"sudo apt install clang"},{"t0":166.45,"t1":169.46,"text":"apt 算出 clang 还需要 30 个“小伙伴”"},{"t0":169.5,"t1":173.39,"text":"全都住在一台叫 archive.ubuntu.com 的服务器上"},{"t0":173.76,"t1":176.21,"text":"它到底在……哪儿呢？"},{"t0":176.83,"t1":179.56,"text":"电脑要的是数字，不是名字"},{"t0":179.93,"t1":183.86,"text":"于是你的电脑去问域名解析器，它再去问根服务器"},{"t0":183.9,"t1":187.54,"text":"根服务器指向 .com，.com 再指向 ubuntu.com"},{"t0":187.58,"t1":189.99,"text":"最后由它给出一个地址"},{"t0":190.61,"t1":193.5,"text":"每台电脑都是一座层层叠起的塔"},{"t0":193.87,"t1":196.25,"text":"消息先沿着我们这座塔往下走"},{"t0":196.3,"t1":200.35,"text":"先裹上 TCP，再裹上 IP，再装进 Wi-Fi 帧"},{"t0":200.39,"t1":202.69,"text":"最后化作无线电波离开"},{"t0":203.31,"t1":205.33,"text":"路由器是矮一些的塔"},{"t0":205.37,"t1":207.51,"text":"它们只爬到 IP 那一层"},{"t0":207.55,"t1":209.66,"text":"读出地址，再把它转发出去"},{"t0":210.03,"t1":214.08,"text":"接着，它变成玻璃光纤里的光，有时还要沿着海底走"},{"t0":214.12,"t1":217.03,"text":"速度是每秒 20 万公里"},{"t0":217.65,"t1":219.93,"text":"到了另一头，先来一次握手"},{"t0":219.97,"t1":222.88,"text":"SYN、SYN-ACK、ACK"},{"t0":223.25,"t1":226.2,"text":"然后服务器开始发送，一开始很谨慎"},{"t0":226.29,"t1":228.63,"text":"先发 10 个数据包，再翻一倍"},{"t0":228.67,"t1":231.58,"text":"再翻一倍，直到把线路占满"},{"t0":232.2,"t1":236.3,"text":"你的编译器，是分成大约 7.7 万个数据包送来的"},{"t0":236.67,"t1":239.88,"text":"有的走了别的路线，有的到达顺序乱了"},{"t0":239.97,"t1":242.11,"text":"还有几个丢了，只好重发"},{"t0":242.48,"t1":247.35,"text":"TCP 给每个字节都编了号，所以它们又排回完美的一行"},{"t0":247.97,"t1":251.76,"text":"默认情况下，这一切都走普通的 HTTP"},{"t0":251.8,"t1":252.94,"text":"没有加密"},{"t0":253.31,"t1":254.25,"text":"这没关系"},{"t0":254.41,"t1":257.14,"text":"apt 认的是封印，不是路"},{"t0":257.51,"t1":261.74,"text":"每个软件包的指纹，都列在 Ubuntu 签名的索引里"},{"t0":261.78,"t1":264.18,"text":"而你的电脑早就有了密钥"},{"t0":264.8,"t1":268.2,"text":"一个软件包，就是归档里面套着归档"},{"t0":268.57,"t1":273.21,"text":"dpkg 把它们拆开，文件各就各位"},{"t0":273.58,"t1":274.67,"text":"有意思的是"},{"t0":274.74,"t1":277.05,"text":"clang 的大部分，其实早就在这儿了"},{"t0":277.42,"t1":280.37,"text":"你的显卡驱动，用的就是同一套编译器库"},{"t0":280.41,"t1":281.43,"text":"用来处理着色器"},{"t0":282.05,"t1":285.22,"text":"现在输入 clang，shell 会顺着你的 PATH 找下去"},{"t0":285.26,"t1":287.67,"text":"也就是一串文件夹，直到找到它为止"},{"t0":288.04,"t1":290.3,"text":"配环境，有一半就是这件事"},{"t0":290.67,"t1":293.26,"text":"另一半，是读报错信息"},{"t0":293.88,"t1":295.01,"text":"还有一件事"},{"t0":295.38,"t1":297.56,"text":"clang 本身就是一个编译出来的程序"},{"t0":297.93,"t1":299.03,"text":"是谁编译了它？"},{"t0":299.4,"t1":300.69,"text":"另一个编译器"},{"t0":301.06,"t1":302.04,"text":"那它呢？"},{"t0":302.41,"t1":303.53,"text":"一个更老的"},{"t0":303.9,"t1":305.78,"text":"沿着这条链往回追，追得足够远"},{"t0":305.82,"t1":308.46,"text":"就会追到有人亲手敲下的机器码"},{"t0":308.83,"t1":312.56,"text":"你信任的每个编译器，都有你永远见不到的祖先"},{"t0":313.18,"t1":314.89,"text":"现在，你打开编辑器"},{"t0":315.26,"t1":318.43,"text":"一次 fork、一次 exec，再过一遍加载器"},{"t0":318.53,"t1":322.25,"text":"它向合成器要了一个窗口，画出一张空白页"},{"t0":322.62,"t1":323.81,"text":"它的 Run 按钮呢？"},{"t0":324.18,"t1":325.67,"text":"不过是一条存好的命令"},{"t0":326.29,"t1":328.19,"text":"我们来跟踪一次按键"},{"t0":328.23,"t1":330.01,"text":"Hello 里的 H"},{"t0":330.38,"t1":332.5,"text":"你的键盘并不认识字母"},{"t0":332.87,"t1":335.08,"text":"它报告的是位置"},{"t0":335.12,"t1":336.67,"text":"Shift 键，还有 11 号键"},{"t0":337.04,"t1":339.11,"text":"而且要等被问到了，它才开口"},{"t0":339.48,"t1":343.06,"text":"电脑会轮询它，每秒最多 1000 次"},{"t0":343.68,"t1":346.55,"text":"内核把这份报告变成事件"},{"t0":346.59,"t1":348.83,"text":"42、35"},{"t0":349.2,"t1":352.17,"text":"合成器把它们交给你正看着的那个窗口"},{"t0":352.23,"t1":355.21,"text":"只有到了那里，你的键盘布局才做出决定"},{"t0":355.26,"t1":356.56,"text":"大写 H"},{"t0":357.18,"t1":360.25,"text":"编辑器插入它，并给这一行重新上色"},{"t0":360.38,"t1":363.22,"text":"一个迷你词法分析器，每敲一键都跑一次"},{"t0":363.63,"t1":367.64,"text":"同时，clangd 用 clang 真正的前端处理你的文件"},{"t0":368.01,"t1":371.2,"text":"所以你还没打完 printf，它就认出来了"},{"t0":371.82,"t1":376.81,"text":"所以等你点下 Run，代码已经被“半编译”了几十次"},{"t0":377.18,"t1":378.51,"text":"只是没人告诉你"},{"t0":379.13,"t1":381.46,"text":"最后，这个 H 被画出来"},{"t0":381.66,"t1":384.36,"text":"字体里的曲线，被填充成像素"},{"t0":384.46,"t1":387.02,"text":"和所有窗口混合成一帧"},{"t0":387.06,"t1":389.21,"text":"在下一次刷新时发送出去"},{"t0":389.58,"t1":391.3,"text":"从指尖到光子"},{"t0":391.34,"t1":393.01,"text":"几十毫秒"},{"t0":393.38,"t1":395.52,"text":"现在，把这个过程再重复 80 次"},{"t0":396.14,"t1":397.5,"text":"Ctrl+S"},{"t0":397.87,"t1":401.02,"text":"编辑器调用 write，内核回复：搞定"},{"t0":401.39,"t1":402.42,"text":"它在撒个小谎"},{"t0":402.46,"t1":405.46,"text":"你的文件其实还在内存里，在页缓存中"},{"t0":405.83,"t1":407.75,"text":"几秒后，它才被刷写下去"},{"t0":407.79,"t1":410.57,"text":"穿过文件系统，写进 SSD"},{"t0":411.19,"t1":416.43,"text":"在那里，Hello, world 变成了电荷\n被困在几百个微小的存储单元里"},{"t0":416.8,"t1":419.19,"text":"即使断了电，它也能熬过这一夜"},{"t0":419.23,"t1":422.35,"text":"它待的，正是今早你的内核出发时的那种芯片"},{"t0":422.97,"t1":423.86,"text":"通电"},{"t0":424.23,"t1":425.37,"text":"固件"},{"t0":425.74,"t1":426.75,"text":"内核"},{"t0":427.12,"t1":428.39,"text":"1 号进程"},{"t0":428.76,"t1":429.92,"text":"桌面"},{"t0":430.29,"t1":432.72,"text":"7.7 万个数据包"},{"t0":433.09,"t1":434.55,"text":"签了名的软件包"},{"t0":434.92,"t1":435.88,"text":"编辑器"},{"t0":436.25,"t1":437.66,"text":"80 次按键"},{"t0":438.03,"t1":439.33,"text":"一次保存"},{"t0":439.7,"t1":441.87,"text":"这一切，只为了走到这里"},{"t0":442.49,"t1":444.43,"text":"光标就停在按钮上"},{"t0":444.8,"t1":446.12,"text":"一切都准备好了"},{"t0":446.49,"t1":447.39,"text":"来吧"},{"t0":447.76,"t1":448.55,"text":"点下去"}],"explore":{"zones":[{"dzIn":200,"why":"the terminal window fades early when the camera nears it (D's own near fade starts at eff 250)","t0":161.18,"t1":175.4},{"explore":false,"why":"the night map is laid out from the camera (D places it with fromScreen/camAt): pan and dolly carry it along, a tilt drops the sea and the threads","t0":175.4,"t1":195.08},{"explore":false,"why":"the same camera-anchored night map, with the handshake and the packet flow on it","t0":217.43,"t1":243.29},{"yaw":10,"pitch":7,"why":"a close-up on the H, a few hundred units from the lens: a full tilt swings the glyph out of frame","t0":379.21,"t1":394.15}]},"audio":{"m4a":"audio/film.m4a","duration":452.2},"build":{"at":"2026-10-10 18:59:41","project":"before-run","chaptersFrom":"web/web.json","zhFrom":"script/subtitles.zh-Hans.json"}};
